@@ -0,0 +1,43 @@
+import { describe, expect, it } from 'vitest';
+import { existsSync, readFileSync } from 'node:fs';
+import { join, resolve } from 'node:path';
+
+const ROOT = resolve(__dirname, '..');
+const FILE = join(ROOT, 'gemini-extension.json');
+
+function read(path: string): string {
+  return readFileSync(path, 'utf8');
+}
+
+describe('Gemini CLI extension manifest', () => {
+  it('exists, is valid JSON and ends with a newline', () => {
+    expect(existsSync(FILE)).toBe(true);
+    const text = read(FILE);
+    expect(text.endsWith('\n')).toBe(true);
+    expect(() => JSON.parse(text)).not.toThrow();
+  });
+
+  it('has name, version and description', () => {
+    const m = JSON.parse(read(FILE));
+    expect(m.name).toBe('vn-skills');
+    expect(typeof m.version).toBe('string');
+    expect(m.version.length).toBeGreaterThan(0);
+    expect(typeof m.description).toBe('string');
+    expect(m.description.length).toBeGreaterThan(0);
+  });
+
+  it('version equals packages/mcp/package.json version', () => {
+    const m = JSON.parse(read(FILE));
+    const mcp = JSON.parse(read(join(ROOT, 'packages', 'mcp', 'package.json')));
+    expect(m.version).toBe(mcp.version);
+  });
+
+  it('declares the vn-skills MCP server pinned to the same version', () => {
+    const m = JSON.parse(read(FILE));
+    const mcp = JSON.parse(read(join(ROOT, 'packages', 'mcp', 'package.json')));
+    expect(m.mcpServers['vn-skills']).toEqual({
+      command: 'npx',
+      args: ['-y', `@vn-skills/mcp@${mcp.version}`],
+    });
+  });
+});

