+/** Find wards by exact postal code and provinces whose postal prefix starts the code. */
+export function findByPostalCode(code: string): Result<{
+  code: string;
+  wards: Array<{
+    code: string;
+    name: string;
+    postalCode: string;
+    province: { code: string; name: string };
+  }>;
+  provinces: Array<{ code: string; name: string; postalPrefix: string }>;
+}> {
+  if (typeof code !== 'string') return fail('INVALID_FORMAT', 'Postal code must be a string');
+  const q = code.replace(/\s+/g, '');
+  if (!q) return fail('EMPTY', 'Postal code is empty');
+  if (!/^\d+$/.test(q)) return fail('INVALID_FORMAT', 'Postal code must contain digits only');
+  const wards = PROVINCES.flatMap((p) =>
+    p.wards
+      .filter((w) => w.postalCode === q)
+      .map((w) => ({
+        code: w.code,
+        name: w.name,
+        postalCode: q,
+        province: { code: p.code, name: p.name },
+      })),
+  );
+  const provinces = PROVINCES.filter((p) => p.postalPrefix && q.startsWith(p.postalPrefix)).map(
+    (p) => ({ code: p.code, name: p.name, postalPrefix: p.postalPrefix as string }),
+  );
+  if (wards.length === 0 && provinces.length === 0)
+    return fail(
+      'NOT_FOUND',
+      `No ward or province matches postal code "${q}"`,
+      'Coverage depends on the upstream dataset; not every code is listed.',
+    );
+  return { ok: true, code: q, wards, provinces };
+}
