+  const prefixed = PROVINCES.find((p) => p.postalPrefix && /^\d+$/.test(p.postalPrefix))!;
+
+  it.each(cases(golden.findByPostalCode))('golden: %s', (_, c) => {
+    expect(findByPostalCode(c.input)).toMatchObject(c.expected);
+  });
+  it('exact ward match from bundled data', () => {
+    const r = findByPostalCode(sampleCode);
+    expect(r.ok).toBe(true);
+    if (!r.ok) return;
+    expect(r.code).toBe(sampleCode);
+    const hit = r.wards.find((w) => w.code === sample.w.code)!;
+    expect(hit).toMatchObject({
+      name: sample.w.name,
+      postalCode: sampleCode,
+      province: { code: sample.p.code, name: sample.p.name },
+    });
+  });
+  it('returns every ward sharing the code', () => {
+    const r = findByPostalCode(sampleCode);
+    const expected = withCode.filter((x) => x.w.postalCode === sampleCode).map((x) => x.w.code);
+    expect(r.ok && r.wards.map((w) => w.code).sort()).toEqual(expected.sort());
+  });
+  it('ward match also reports the owning province prefix', () => {
+    const w = withCode.find((x) => x.p.postalPrefix === prefixed.postalPrefix)!;
+    const r = findByPostalCode(w.w.postalCode!);
+    expect(r.ok && r.provinces.map((p) => p.code)).toContain(prefixed.code);
+  });
+  it('strips spaces', () => {
+    const spaced = sampleCode.slice(0, 2) + ' ' + sampleCode.slice(2) + ' ';
+    expect(findByPostalCode(spaced)).toEqual(findByPostalCode(sampleCode));
+  });
+  it('empty and whitespace-only -> EMPTY', () => {
+    for (const v of ['', '   ']) {
+      const r = findByPostalCode(v);
+      expect(r.ok === false && r.error.code).toBe('EMPTY');
+    }
+  });
+  it('letters / punctuation -> INVALID_FORMAT', () => {
+    for (const v of ['abc', '11a20', '-11120', '11.120']) {
+      const r = findByPostalCode(v);
+      expect(r.ok === false && r.error.code).toBe('INVALID_FORMAT');
+    }
+  });
+  it('unknown code -> NOT_FOUND with upstream-coverage hint', () => {
+    const known = new Set(withCode.map((x) => x.w.postalCode));
+    let n = 1;
+    while (known.has(String(n).padStart(6, '0'))) n++;
+    const r = findByPostalCode(String(n).padStart(6, '0'));
+    expect(r.ok === false && r.error.code).toBe('NOT_FOUND');
+    expect(JSON.stringify(r)).toMatch(/upstream|dataset/i);
+  });
+  it('null / undefined / number -> ok:false without throwing', () => {
+    for (const v of [null, undefined, 11120, {}]) {
+      expect(() => findByPostalCode(v as never)).not.toThrow();
+      expect(findByPostalCode(v as never).ok).toBe(false);
+    }
+  });
+  it('does not mutate bundled data', () => {
+    const before = JSON.stringify(PROVINCES[0]);
+    findByPostalCode(sampleCode);
+    expect(JSON.stringify(PROVINCES[0])).toBe(before);
+  });
+});
