diff --git a/README.md b/README.md
index d70bb58..6b9769e 100644
--- a/README.md
+++ b/README.md
@@ -164,6 +164,16 @@ Then point your client at it (it runs `docker run -i --rm vn-skills-mcp`):

 Other clients: use the generic `mcpServers` block above. AI agents (e.g. Cline) can follow [llms-install.md](llms-install.md).

+### HTTP mode
+
+For a shared or remote server, run the opt-in Streamable HTTP transport (stateless, `POST /mcp`):
+
+```bash
+npx -y @vn-skills/mcp --http --port 3000   # http://127.0.0.1:3000/mcp
+```
+
+It binds to `127.0.0.1` by default; use `--host 0.0.0.0` to expose it (e.g. `docker run -p 3000:3000 vn-skills-mcp --http --host 0.0.0.0`). Requests with a non-localhost `Origin` header get 403 unless you pass `--allow-origin <origin>` (repeatable). Without `--http` the server uses stdio.
+
 ## Library

 ```ts
diff --git a/README.vi.md b/README.vi.md
index bdf062f..5351d55 100644
--- a/README.vi.md
+++ b/README.vi.md
@@ -162,6 +162,16 @@ Sau đó trỏ client tới image (chạy `docker run -i --rm vn-skills-mcp`):

 Client khác: dùng khối `mcpServers` chung ở trên. Agent AI (ví dụ Cline) có thể làm theo [llms-install.md](llms-install.md).

+### Chế độ HTTP
+
+Để dùng chung hoặc từ xa, chạy transport Streamable HTTP (tùy chọn, không lưu session, `POST /mcp`):
+
+```bash
+npx -y @vn-skills/mcp --http --port 3000   # http://127.0.0.1:3000/mcp
+```
+
+Mặc định chỉ lắng nghe trên `127.0.0.1`; dùng `--host 0.0.0.0` để mở ra ngoài (ví dụ `docker run -p 3000:3000 vn-skills-mcp --http --host 0.0.0.0`). Request có header `Origin` không phải localhost sẽ bị từ chối (403) trừ khi thêm `--allow-origin <origin>` (có thể lặp lại). Không có `--http` thì server dùng stdio.
+
 ## Thư viện

 ```ts
diff --git a/packages/mcp/src/index.ts b/packages/mcp/src/index.ts
index 1fab4b1..065566a 100644
--- a/packages/mcp/src/index.ts
+++ b/packages/mcp/src/index.ts
@@ -1,7 +1,79 @@
+import { createServer as createHttpServer } from 'node:http';
 import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
+import { StreamableHTTPServerTransport } from '@modelcontextprotocol/sdk/server/streamableHttp.js';
 import { createServer } from './server.js';

+interface HttpOptions {
+  port: number;
+  host: string;
+  allowOrigins: string[];
+}
+
+function parseHttpArgs(argv: string[]): HttpOptions | null {
+  if (!argv.includes('--http')) return null;
+  const opts: HttpOptions = { port: 3000, host: '127.0.0.1', allowOrigins: [] };
+  for (let i = 0; i < argv.length; i++) {
+    const arg = argv[i];
+    const next = () => {
+      const v = argv[++i];
+      if (v === undefined) throw new Error(`${arg} requires a value`);
+      return v;
+    };
+    if (arg === '--port') {
+      const port = Number(next());
+      if (!Number.isInteger(port) || port < 0 || port > 65535) throw new Error('invalid --port');
+      opts.port = port;
+    } else if (arg === '--host') opts.host = next();
+    else if (arg === '--allow-origin') opts.allowOrigins.push(next());
+  }
+  return opts;
+}
+
+function isLocalOrigin(origin: string): boolean {
+  try {
+    const { hostname } = new URL(origin);
+    return ['localhost', '127.0.0.1', '[::1]'].includes(hostname);
+  } catch {
+    return false;
+  }
+}
+
+function startHttp(opts: HttpOptions) {
+  const http = createHttpServer((req, res) => {
+    const reply = (status: number, message: string) => {
+      res.writeHead(status, { 'content-type': 'application/json' });
+      res.end(JSON.stringify({ jsonrpc: '2.0', error: { code: -32000, message }, id: null }));
+    };
+    const origin = req.headers.origin;
+    if (origin && !isLocalOrigin(origin) && !opts.allowOrigins.includes(origin)) {
+      return reply(403, 'Forbidden origin');
+    }
+    const path = (req.url ?? '').split('?')[0];
+    if (path !== '/mcp') return reply(404, 'Not found');
+
+    const server = createServer();
+    const transport = new StreamableHTTPServerTransport({ sessionIdGenerator: undefined });
+    res.on('close', () => {
+      void transport.close();
+      void server.close();
+    });
+    server
+      .connect(transport)
+      .then(() => transport.handleRequest(req, res))
+      .catch(() => {
+        if (!res.headersSent) reply(500, 'Internal server error');
+      });
+  });
+  http.listen(opts.port, opts.host, () => {
+    const { port } = http.address() as { port: number };
+    const host = opts.host.includes(':') ? `[${opts.host}]` : opts.host;
+    process.stderr.write(`vn-skills MCP server listening on http://${host}:${port}/mcp\n`);
+  });
+}
+
 async function main() {
+  const http = parseHttpArgs(process.argv.slice(2));
+  if (http) return startHttp(http);
   const server = createServer();
   const transport = new StdioServerTransport();
   await server.connect(transport);
diff --git a/tests/mcp-http.test.ts b/tests/mcp-http.test.ts
new file mode 100644
index 0000000..2d279cd
--- /dev/null
+++ b/tests/mcp-http.test.ts
@@ -0,0 +1,106 @@
+import { afterAll, beforeAll, describe, expect, it } from 'vitest';
+import { spawn, type ChildProcess } from 'node:child_process';
+import { createServer } from 'node:net';
+import { resolve } from 'node:path';
+import { Client } from '@modelcontextprotocol/sdk/client/index.js';
+import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';
+
+const SERVER = resolve(__dirname, '..', 'packages', 'mcp', 'dist', 'index.js');
+
+const freePort = () =>
+  new Promise<number>((res, rej) => {
+    const s = createServer();
+    s.once('error', rej);
+    s.listen(0, '127.0.0.1', () => {
+      const { port } = s.address() as { port: number };
+      s.close(() => res(port));
+    });
+  });
+
+type Rpc = { result?: { serverInfo?: unknown; tools?: Array<{ name: string }> } };
+
+const rpc = async (url: string, body: unknown, headers: Record<string, string> = {}) => {
+  const res = await fetch(url, {
+    method: 'POST',
+    headers: {
+      'content-type': 'application/json',
+      accept: 'application/json, text/event-stream',
+      ...headers,
+    },
+    body: JSON.stringify(body),
+  });
+  const raw = await res.text();
+  const data = raw
+    .split('\n')
+    .map((l) => (l.startsWith('data:') ? l.slice(5).trim() : l.trim()))
+    .find((l) => l.startsWith('{'));
+  return { status: res.status, json: data ? (JSON.parse(data) as Rpc) : null };
+};
+
+const init = {
+  jsonrpc: '2.0',
+  id: 1,
+  method: 'initialize',
+  params: {
+    protocolVersion: '2025-06-18',
+    capabilities: {},
+    clientInfo: { name: 'test', version: '0.0.0' },
+  },
+};
+
+describe('vn-skills MCP server over Streamable HTTP', () => {
+  let proc: ChildProcess;
+  let base: string;
+  let stderr = '';
+
+  beforeAll(async () => {
+    const port = await freePort();
+    base = `http://127.0.0.1:${port}`;
+    proc = spawn(process.execPath, [SERVER, '--http', '--port', String(port)], {
+      stdio: ['ignore', 'ignore', 'pipe'],
+    });
+    proc.stderr!.on('data', (d: Buffer) => (stderr += d.toString()));
+    const deadline = Date.now() + 4_000;
+    while (Date.now() < deadline && !stderr.includes(String(port))) {
+      await new Promise((r) => setTimeout(r, 50));
+    }
+  });
+  afterAll(() => {
+    proc?.kill();
+  });
+
+  it('prints the listening URL to stderr', () => {
+    expect(stderr).toContain(`http://127.0.0.1:`);
+  });
+
+  it('initialize then tools/list returns the same tools as stdio', async () => {
+    const i = await rpc(`${base}/mcp`, init);
+    expect(i.status).toBe(200);
+    expect(i.json?.result?.serverInfo).toBeTruthy();
+    const l = await rpc(`${base}/mcp`, { jsonrpc: '2.0', id: 2, method: 'tools/list' });
+    expect(l.status).toBe(200);
+    const httpNames = l.json!.result!.tools!.map((t) => t.name).sort();
+
+    const client = new Client({ name: 'test', version: '0.0.0' });
+    await client.connect(new StdioClientTransport({ command: process.execPath, args: [SERVER] }));
+    const stdioNames = (await client.listTools()).tools.map((t) => t.name).sort();
+    await client.close();
+    expect(httpNames.length).toBeGreaterThan(0);
+    expect(httpNames).toEqual(stdioNames);
+  });
+
+  it('rejects a foreign Origin with 403', async () => {
+    const r = await rpc(`${base}/mcp`, init, { origin: 'https://evil.example' });
+    expect(r.status).toBe(403);
+  });
+
+  it('accepts a localhost Origin', async () => {
+    const r = await rpc(`${base}/mcp`, init, { origin: 'http://localhost:5173' });
+    expect(r.status).toBe(200);
+  });
+
+  it('returns 404 for other paths', async () => {
+    const res = await fetch(`${base}/other`, { method: 'POST', body: '{}' });
+    expect(res.status).toBe(404);
+  });
+});

