index 0000000..e15157a
--- /dev/null
+++ b/packages/core/src/lunar/anniversary.ts
@@ -0,0 +1,105 @@
+import { lunarToSolar, lunarMonthLength, leapMonthOf, isValidSolarDate } from './convert.js';
+import { fail, type Result } from '../shared/result.js';
+
+export type AnniversarySkip = 'omit' | 'backward' | 'forward';
+
+export interface LunarAnniversary {
+  lunarYear: number;
+  solar: string;
+  lunar: { day: number; month: number; leap: boolean };
+  adjusted: 'none' | 'backward' | 'forward';
+}
+
+const pad = (n: number) => String(n).padStart(2, '0');
+
+/**
+ * Solar dates of a yearly lunar date (ngày giỗ, lunar birthday) on or after `from` (YYYY-MM-DD).
+ *
+ * Missing dates follow the SKIP rule part of RFC 7529 (https://www.rfc-editor.org/rfc/rfc7529.txt), paraphrased:
+ * OMIT (default) drops the instance; BACKWARD moves it to the last day of the previous month; FORWARD moves it to
+ * the first day of the next month. For a missing day 30 that is the last day of that month (BACKWARD) or day 1 of
+ * the next (FORWARD). For a missing leap month the previous month is the regular month of the same number (its last
+ * day, whatever the day number) and the next month the one after it (day 1).
+ * `omittedYears` lists only omitted years whose would-be date is on or after `from`.
+ */
+export function lunarAnniversaries(
+  date: { day: number; month: number; leap?: boolean },
+  opts: { from: string; count?: number; skip?: AnniversarySkip },
+): Result<{ occurrences: LunarAnniversary[]; omittedYears: number[] }> {
+  const { day, month } = date;
+  const leap = date.leap === true;
+  const count = opts.count ?? 5;
+  const skip = opts.skip ?? 'omit';
+  if (![day, month].every(Number.isInteger) || day < 1 || day > 30 || month < 1 || month > 12) {
+    return fail(
+      'INVALID_DATE',
+      `Invalid lunar date ${day}/${month}`,
+      'Lunar day 1-30, month 1-12.',
+    );
+  }
+  if (!Number.isInteger(count) || count < 1 || count > 50) {
+    return fail('INVALID_COUNT', `count must be an integer from 1 to 50, got ${count}`);
+  }
+  if (!['omit', 'backward', 'forward'].includes(skip)) {
+    return fail('INVALID_SKIP', `Invalid skip "${skip}"`, 'Use omit, backward or forward.');
+  }
+  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(opts.from ?? ''));
+  if (!m || !isValidSolarDate(Number(m[3]), Number(m[2]), Number(m[1]))) {
+    return fail('INVALID_DATE', `Cannot parse from date "${opts.from}"`, 'Use yyyy-mm-dd.');
+  }
+  const from = opts.from;
+  const solarOf = (d: number, mo: number, y: number, lp: boolean): string | null => {
+    const r = lunarToSolar(d, mo, y, lp);
+    return r.ok ? `${r.year}-${pad(r.month)}-${pad(r.day)}` : null;
+  };
+  if (Number(m[1]) < 1800 || Number(m[1]) > 2199) {
+    return fail('OUT_OF_RANGE', 'Supported years: 1800-2199');
+  }
+
+  const occurrences: LunarAnniversary[] = [];
+  const omittedYears: number[] = [];
+  // The lunar year may start in the previous solar year, so begin one year early.
+  for (let y = Math.max(1800, Number(m[1]) - 1); occurrences.length < count; y++) {
+    if (y > 2199) return fail('OUT_OF_RANGE', 'Supported years: 1800-2199');
+    let found: LunarAnniversary | null = null;
+    const hasMonth = !leap || leapMonthOf(y) === month;
+    const len = hasMonth ? lunarMonthLength(month, y, leap) : null;
+    if (len !== null && day <= len) {
+      found = {
+        lunarYear: y,
+        solar: solarOf(day, month, y, leap)!,
+        lunar: { day, month, leap },
+        adjusted: 'none',
+      };
+    } else if (skip === 'backward') {
+      // Missing leap month: last day of the regular month of that number; missing day: last day of the month.
+      const lp = hasMonth && leap;
+      const d = lunarMonthLength(month, y, lp)!;
+      found = {
+        lunarYear: y,
+        solar: solarOf(d, month, y, lp)!,
+        lunar: { day: d, month, leap: lp },
+        adjusted: 'backward',
+      };
+    } else if (skip === 'forward') {
+      // The month after a regular month that has a leap twin is the leap month itself.
+      const toLeap = hasMonth && !leap && leapMonthOf(y) === month;
+      const wrap = !toLeap && month === 12;
+      const target = { m: toLeap ? month : wrap ? 1 : month + 1, lp: toLeap };
+      const s = solarOf(1, target.m, wrap ? y + 1 : y, target.lp);
+      if (s === null) return fail('OUT_OF_RANGE', 'Supported years: 1800-2199');
+      found = {
+        lunarYear: y,
+        solar: s,
+        lunar: { day: 1, month: target.m, leap: target.lp },
+        adjusted: 'forward',
+      };
+    } else {
+      const lp = hasMonth && leap;
+      const last = solarOf(lunarMonthLength(month, y, lp)!, month, y, lp)!;
+      if (last >= from) omittedYears.push(y);
+    }
+    if (found && found.solar >= from) occurrences.push(found);
+  }
+  return { ok: true, occurrences, omittedYears };
+}
