+++ b/tests/lunar-anniversary.test.ts
@@ -0,0 +1,196 @@
+import { describe, expect, it } from 'vitest';
+import { lunarAnniversaries, lunarToSolar, lunarMonthLength, leapMonthOf } from '@vn-skills/core';
+
+const iso = (s: { year: number; month: number; day: number }) =>
+  `${s.year}-${String(s.month).padStart(2, '0')}-${String(s.day).padStart(2, '0')}`;
+
+function solarOf(d: number, m: number, y: number, leap = false): string {
+  const r = lunarToSolar(d, m, y, leap);
+  if (!r.ok) throw new Error('lunarToSolar failed');
+  return iso(r);
+}
+
+function ok<T extends { ok: boolean }>(r: T) {
+  if (!r.ok) throw new Error(`expected ok: ${JSON.stringify(r)}`);
+  return r as Extract<T, { ok: true }>;
+}
+
+// First year >= 2000 where the 30th of `month` does not exist (29-day month).
+function shortYear(month: number): number {
+  for (let y = 2000; y < 2100; y++) if (lunarMonthLength(month, y) === 29) return y;
+  throw new Error('no short month found');
+}
+
+describe('lunarAnniversaries', () => {
+  it('1/1 matches Tết 2027 = 2027-02-06', () => {
+    const r = ok(lunarAnniversaries({ day: 1, month: 1 }, { from: '2027-01-01', count: 1 }));
+    expect(r.occurrences[0]).toMatchObject({
+      lunarYear: 2027,
+      solar: '2027-02-06',
+      lunar: { day: 1, month: 1, leap: false },
+      adjusted: 'none',
+    });
+  });
+
+  it('defaults to 5 occurrences', () => {
+    const r = ok(lunarAnniversaries({ day: 15, month: 7 }, { from: '2025-01-01' }));
+    expect(r.occurrences).toHaveLength(5);
+    expect(r.omittedYears).toEqual([]);
+  });
+
+  it('matches lunarToSolar for consecutive years', () => {
+    const r = ok(lunarAnniversaries({ day: 15, month: 7 }, { from: '2025-01-01', count: 4 }));
+    expect(r.occurrences.map((o) => [o.lunarYear, o.solar])).toEqual(
+      [2025, 2026, 2027, 2028].map((y) => [y, solarOf(15, 7, y)]),
+    );
+  });
+
+  it('includes an occurrence falling exactly on from', () => {
+    const d = solarOf(15, 7, 2025);
+    const r = ok(lunarAnniversaries({ day: 15, month: 7 }, { from: d, count: 1 }));
+    expect(r.occurrences[0]?.solar).toBe(d);
+  });
+
+  it('skips this year when from is after its occurrence', () => {
+    const r = ok(lunarAnniversaries({ day: 15, month: 7 }, { from: '2025-12-31', count: 2 }));
+    expect(r.occurrences.map((o) => o.lunarYear)).toEqual([2026, 2027]);
+    expect(r.occurrences[0]?.solar).toBe(solarOf(15, 7, 2026));
+  });
+
+  it('returns occurrences in ascending order on or after from', () => {
+    const from = '2026-06-15';
+    const r = ok(lunarAnniversaries({ day: 3, month: 3 }, { from, count: 10 }));
+    const dates = r.occurrences.map((o) => o.solar);
+    expect(dates).toEqual([...dates].sort());
+    expect(dates.every((d) => d >= from)).toBe(true);
+  });
+
+  it('count limits the result and rejects > 50', () => {
+    expect(
+      ok(lunarAnniversaries({ day: 1, month: 1 }, { from: '2020-01-01', count: 3 })).occurrences,
+    ).toHaveLength(3);
+    expect(
+      ok(lunarAnniversaries({ day: 1, month: 1 }, { from: '1900-01-01', count: 50 })).occurrences,
+    ).toHaveLength(50);
+    expect(
+      lunarAnniversaries({ day: 1, month: 1 }, { from: '2020-01-01', count: 51 }),
+    ).toMatchObject({ ok: false });
+    expect(
+      lunarAnniversaries({ day: 1, month: 1 }, { from: '2020-01-01', count: 0 }),
+    ).toMatchObject({ ok: false });
+  });
+
+  describe('day 30 in a 29-day month', () => {
+    const y = shortYear(2);
+    const from = `${y}-01-01`;
+
+    it('omit (default) drops the year and reports it', () => {
+      const r = ok(lunarAnniversaries({ day: 30, month: 2 }, { from, count: 3 }));
+      expect(r.omittedYears).toContain(y);
+      expect(r.occurrences.map((o) => o.lunarYear)).not.toContain(y);
+      expect(r.occurrences.every((o) => o.adjusted === 'none')).toBe(true);
+      expect(r.occurrences).toHaveLength(3);
+    });
+
+    it('explicit omit equals default', () => {
+      expect(lunarAnniversaries({ day: 30, month: 2 }, { from, count: 3, skip: 'omit' })).toEqual(
+        lunarAnniversaries({ day: 30, month: 2 }, { from, count: 3 }),
+      );
+    });
+
+    it('backward uses the last day of that month (RFC 7529)', () => {
+      const r = ok(lunarAnniversaries({ day: 30, month: 2 }, { from, count: 3, skip: 'backward' }));
+      const o = r.occurrences.find((x) => x.lunarYear === y);
+      expect(o).toMatchObject({
+        solar: solarOf(29, 2, y),
+        adjusted: 'backward',
+        lunar: { day: 29, month: 2, leap: false },
+      });
+      expect(r.omittedYears).toEqual([]);
+    });
+
+    it('forward uses the first day of the next month (RFC 7529)', () => {
+      const r = ok(lunarAnniversaries({ day: 30, month: 2 }, { from, count: 3, skip: 'forward' }));
+      const o = r.occurrences.find((x) => x.lunarYear === y);
+      expect(o).toMatchObject({
+        solar: solarOf(1, 3, y),
+        adjusted: 'forward',
+        lunar: { day: 1, month: 3 },
+      });
+    });
+  });
+
+  describe('leap-month anniversary', () => {
+    const leapYear = (() => {
+      for (let y = 2000; y < 2100; y++) {
+        const m = leapMonthOf(y);
+        if (m !== null) return { y, m };
+      }
+      throw new Error('no leap year');
+    })();
+    const { y, m } = leapYear;
+    const from = `${y}-01-01`;
+
+    it('finds the leap month in years that have it and omits others', () => {
+      const r = ok(lunarAnniversaries({ day: 10, month: m, leap: true }, { from, count: 2 }));
+      expect(r.occurrences[0]).toMatchObject({
+        lunarYear: y,
+        solar: solarOf(10, m, y, true),
+        lunar: { day: 10, month: m, leap: true },
+      });
+      expect(r.omittedYears.length).toBeGreaterThan(0);
+      for (const o of r.occurrences) expect(leapMonthOf(o.lunarYear)).toBe(m);
+    });
+
+    it('leap:false uses the regular month even in a year with a leap month', () => {
+      const r = ok(lunarAnniversaries({ day: 10, month: m }, { from, count: 1 }));
+      expect(r.occurrences[0]).toMatchObject({ solar: solarOf(10, m, y), lunar: { leap: false } });
+    });
+
+    it('backward falls back to the regular month in years without the leap month', () => {
+      const r = ok(
+        lunarAnniversaries({ day: 10, month: m, leap: true }, { from, count: 5, skip: 'backward' }),
+      );
+      const missing = r.occurrences.find((o) => leapMonthOf(o.lunarYear) !== m);
+      expect(missing).toMatchObject({ adjusted: 'backward', lunar: { month: m, leap: false } });
+      expect(r.omittedYears).toEqual([]);
+    });
+  });
+
+  describe('invalid input', () => {
+    it.each([
+      [{ day: 0, month: 1 }],
+      [{ day: 31, month: 1 }],
+      [{ day: 1, month: 0 }],
+      [{ day: 1, month: 13 }],
+    ])('INVALID_DATE for %j', (date) => {
+      expect(lunarAnniversaries(date, { from: '2025-01-01' })).toMatchObject({
+        ok: false,
+        error: { code: 'INVALID_DATE' },
+      });
+    });
+
+    it('rejects a malformed from date', () => {
+      expect(lunarAnniversaries({ day: 1, month: 1 }, { from: 'tomorrow' })).toMatchObject({
+        ok: false,
+      });
+    });
+  });
+
+  describe('range boundary', () => {
+    it('OUT_OF_RANGE when the walk passes 2199', () => {
+      expect(
+        lunarAnniversaries({ day: 1, month: 1 }, { from: '2198-01-01', count: 5 }),
+      ).toMatchObject({
+        ok: false,
+        error: { code: 'OUT_OF_RANGE' },
+      });
+    });
+
+    it('returns 2199 occurrence when it fits', () => {
+      const r = ok(lunarAnniversaries({ day: 1, month: 1 }, { from: '2198-06-01', count: 1 }));
+      expect(r.occurrences[0]?.lunarYear).toBe(2199);
+      expect(r.occurrences[0]?.solar).toBe(solarOf(1, 1, 2199));
+    });
+  });
+});
