diff --git a/tests/address-region.test.ts b/tests/address-region.test.ts
new file mode 100644
index 0000000..b815c35
--- /dev/null
+++ b/tests/address-region.test.ts
@@ -0,0 +1,136 @@
+import { describe, expect, it } from 'vitest';
+import { PROVINCES, listRegions, lookupProvince, provincesInRegion } from '@vn-skills/core';
+
+type Region = { id: number | string; name: string; nameEn: string };
+type RegionList = { ok: true; count: number; regions: Region[] };
+type InRegion = { ok: true; region: Region; provinces: Array<{ code: string; name: string }> };
+
+const regionsOf = () => listRegions() as unknown as RegionList;
+const regionOfProvince = (code: string) =>
+  (lookupProvince(code) as unknown as { region: Region }).region;
+const strip = (s: string) =>
+  s.normalize('NFD').replace(/\p{M}/gu, '').replace(/đ/g, 'd').replace(/Đ/g, 'D');
+
+describe('provinces carry a region', () => {
+  it('every province has a region with id, name and nameEn', () => {
+    for (const p of PROVINCES) {
+      const r = (p as unknown as { region?: Region }).region;
+      expect(r, p.name).toBeDefined();
+      expect(r!.name).toBeTruthy();
+      expect(r!.nameEn).toBeTruthy();
+      expect(r!.id).not.toBeUndefined();
+    }
+  });
+  it('provinceInfo (via lookupProvince) includes region', () => {
+    for (const p of PROVINCES) {
+      expect(regionOfProvince(p.code)).toMatchObject({ name: expect.any(String) });
+    }
+  });
+  it('lookup by name and by old name resolves the same region', () => {
+    expect(regionOfProvince('TP.HCM')).toEqual(regionOfProvince('79'));
+  });
+});
+
+describe('listRegions', () => {
+  it('is ok and count matches regions length', () => {
+    const j = regionsOf();
+    expect(j.ok).toBe(true);
+    expect(j.count).toBe(j.regions.length);
+  });
+  it('has exactly the distinct regions used by provinces', () => {
+    const ids = new Set(PROVINCES.map((p) => String(regionOfProvince(p.code).id)));
+    expect(regionsOf().count).toBe(ids.size);
+  });
+  it('has unique ids and names', () => {
+    const rs = regionsOf().regions;
+    expect(new Set(rs.map((r) => String(r.id))).size).toBe(rs.length);
+    expect(new Set(rs.map((r) => r.name)).size).toBe(rs.length);
+  });
+});
+
+describe('provincesInRegion', () => {
+  it('every listed region returns its provinces, and together they cover all 34', () => {
+    const codes: string[] = [];
+    for (const r of regionsOf().regions) {
+      const j = provincesInRegion(r.name) as unknown as InRegion;
+      expect(j.ok, r.name).toBe(true);
+      expect(j.region.name).toBe(r.name);
+      expect(j.provinces.length).toBeGreaterThan(0);
+      for (const p of j.provinces) {
+        expect(regionOfProvince(p.code).name).toBe(r.name);
+        codes.push(p.code);
+      }
+    }
+    expect(codes.sort()).toEqual(PROVINCES.map((p) => p.code).sort());
+  });
+  it('matches region names without diacritics, any case', () => {
+    for (const r of regionsOf().regions) {
+      for (const q of [strip(r.name), strip(r.name).toUpperCase(), r.name.toLowerCase()]) {
+        const j = provincesInRegion(q) as unknown as InRegion;
+        expect(j.ok, q).toBe(true);
+        expect(j.region.name).toBe(r.name);
+      }
+    }
+  });
+  it('matches by English name', () => {
+    const r = regionsOf().regions[0]!;
+    expect((provincesInRegion(r.nameEn) as unknown as InRegion).region.name).toBe(r.name);
+  });
+  it('trims surrounding whitespace', () => {
+    const r = regionsOf().regions[0]!;
+    expect(provincesInRegion(`  ${r.name} `)).toMatchObject({ ok: true });
+  });
+  it('returns NOT_FOUND for unknown input', () => {
+    expect(provincesInRegion('zzzz không tồn tại')).toMatchObject({
+      ok: false,
+      error: { code: 'NOT_FOUND' },
+    });
+  });
+  it('returns EMPTY for empty and blank input', () => {
+    expect(provincesInRegion('')).toMatchObject({ ok: false, error: { code: 'EMPTY' } });
+    expect(provincesInRegion('   ')).toMatchObject({ ok: false, error: { code: 'EMPTY' } });
+  });
+  it('does not throw on non-string input', () => {
+    expect(() => provincesInRegion(null as unknown as string)).not.toThrow();
+    expect(provincesInRegion(undefined as unknown as string)).toMatchObject({ ok: false });
+  });
+});
+
+describe('old province names', () => {
+  it('a pre-merger name resolves through the existing resolver to a region', () => {
+    expect(regionOfProvince('Bà Rịa - Vũng Tàu')).toEqual(regionOfProvince('TP.HCM'));
