+        readFileSync(resolve(__dirname, '..', 'packages', 'core', 'data', f), 'utf8'),
+      ) as unknown;
+    const strip = (s: string) =>
+      s
+        .normalize('NFD')
+        .replace(/[\u0300-\u036f]/g, '')
+        .replace(/đ/g, 'd')
+        .replace(/Đ/g, 'D')
+        .toLowerCase();
+
+    const findArg = async (re: RegExp) => {
+      const { prompts } = await client.listPrompts();
+      for (const p of prompts) {
+        const a = (p.arguments ?? []).find((x) => re.test(x.name));
+        if (a) return { name: p.name, arg: a.name };
+      }
