+    expect(full.VN_AM_LICH!('28/01/2025')).toBe(text);
+    const r = full.VN_AM_LICH!([['28/01/2025'], [new Date(2025, 0, 28, 12)]]) as string[][];
+    expect(r).toEqual([[text], [text]]);
+  });
