+    expect(typeof w).toBe('boolean');
+    expect(full.VN_NGAY_LAM_VIEC!('04/01/2025')).toBe(w);
+    expect(full.VN_NGAY_LAM_VIEC!(new Date(2025, 0, 4, 12))).toBe(w);
+    expect(full.VN_NGAY_LAM_VIEC!([['04/01/2025', '06/01/2025']])).toEqual([
