@@ -0,0 +1,182 @@
+import { afterAll, beforeAll, describe, expect, it } from 'vitest';
+import { spawnSync } from 'node:child_process';
+import { resolve } from 'node:path';
+import { Client } from '@modelcontextprotocol/sdk/client/index.js';
+import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';
+import * as core from '@vn-skills/core';
+
+// Mnemonics from RFC 1456 (VIQR): ' acute, ` grave, ? hook, ~ tilde, . dot below, ( breve, ^ circumflex, + horn, dd.
+type Viqr = (t: string) => {
+  ok: boolean;
+  text?: string;
+  replaced?: number;
+  warnings?: string[];
+  error?: { code: string };
+};
+const viqrToUnicode = (core as unknown as { viqrToUnicode: Viqr }).viqrToUnicode;
+const conv = (s: string) => {
+  const r = viqrToUnicode(s);
+  if (!r.ok) throw new Error(r.error?.code);
+  return r.text;
+};
+
+const CLI = resolve(__dirname, '..', 'packages', 'cli', 'dist', 'index.js');
+const SERVER = resolve(__dirname, '..', 'packages', 'mcp', 'dist', 'index.js');
+
+describe('viqrToUnicode', () => {
+  it('is exported', () => expect(typeof viqrToUnicode).toBe('function'));
+
+  it.each([
+    ["a'", 'á'],
+    ['a`', 'à'],
+    ['a?', 'ả'],
+    ['a~', 'ã'],
+    ['a.', 'ạ'],
+    ["e'", 'é'],
+    ['e`', 'è'],
+    ['e?', 'ẻ'],
+    ['e~', 'ẽ'],
+    ['e.', 'ẹ'],
+    ["i'", 'í'],
+    ['i`', 'ì'],
+    ['i?', 'ỉ'],
+    ['i~', 'ĩ'],
+    ['i.', 'ị'],
+    ["o'", 'ó'],
+    ['o`', 'ò'],
+    ['o?', 'ỏ'],
+    ['o~', 'õ'],
+    ['o.', 'ọ'],
+    ["u'", 'ú'],
+    ['u`', 'ù'],
+    ['u?', 'ủ'],
+    ['u~', 'ũ'],
+    ['u.', 'ụ'],
+    ["y'", 'ý'],
+    ['y`', 'ỳ'],
+    ['y?', 'ỷ'],
+    ['y~', 'ỹ'],
+    ['y.', 'ỵ'],
+  ])('tone %s -> %s', (i, o) => expect(conv(i)).toBe(o));
+
+  it.each([
+    ['a^', 'â'],
+    ["a^'", 'ấ'],
+    ['a^.', 'ậ'],
+    ['a(', 'ă'],
+    ['a(`', 'ằ'],
+    ['a(~', 'ẵ'],
+    ['e^', 'ê'],
+    ['e^~', 'ễ'],
+    ['o^', 'ô'],
+    ['o^?', 'ổ'],
+    ['o+', 'ơ'],
+    ["o+'", 'ớ'],
+    ['u+', 'ư'],
+    ['u+.', 'ự'],
+  ])('vowel %s -> %s', (i, o) => expect(conv(i)).toBe(o));
+
+  it.each([
+    ['dd', 'đ'],
+    ['DD', 'Đ'],
+    ['Dd', 'Đ'],
+    ['dD', 'đ'],
+  ])('d rule %s -> %s', (i, o) => expect(conv(i)).toBe(o));
+
+  it('converts upper case', () => {
+    expect(conv("A'")).toBe('Á');
+    expect(conv('O+')).toBe('Ơ');
+    expect(conv('U+.')).toBe('Ự');
+  });
+
+  it('converts whole phrases', () => {
+    expect(conv('Vie^.t Nam')).toBe('Việt Nam');
+    expect(conv('Ddo^ng Nai')).toBe('Đông Nai');
+    expect(conv('Tru+o+`ng')).toBe('Trường');
+  });
+
+  it('output is NFC', () => {
+    const t = conv("Vie^.t a'")!;
+    expect(t).toBe(t.normalize('NFC'));
+  });
+
+  it('leaves text without VIQR unchanged', () => {
+    expect(conv('Hello world 123')).toBe('Hello world 123');
+  });
+
+  it('RFC escape: backslash makes the mark literal', () => {
+    expect(conv("a\\'")).toBe("a'");
+    expect(conv('a\\^')).toBe('a^');
+    expect(conv('\\\\')).toBe('\\');
+  });
+
+  it('punctuation that follows a non-vowel is kept', () => {
+    expect(conv("Hello, it's 5. Done? Yes.")).toContain('Done?');
+    expect(conv('(1) ~ 2')).toBe('(1) ~ 2');
+  });
+
+  it('reports replaced count', () => {
+    const r = viqrToUnicode("a' e`");
+    expect(r.ok).toBe(true);
+    expect(r.replaced).toBeGreaterThan(0);
+    expect(Array.isArray(r.warnings)).toBe(true);
+  });
+
+  it('empty input is EMPTY', () => {
+    expect(viqrToUnicode('')).toMatchObject({ ok: false, error: { code: 'EMPTY' } });
+  });
+
+  it('non-string input is INVALID_INPUT, not a throw', () => {
+    expect(viqrToUnicode(42 as unknown as string)).toMatchObject({
+      ok: false,
+      error: { code: 'INVALID_INPUT' },
+    });
+    expect(viqrToUnicode(null as unknown as string)).toMatchObject({
+      ok: false,
+      error: { code: 'INVALID_INPUT' },
+    });
+  });
+});
+
+describe('vn-skills text from-viqr', () => {
+  const run = (args: string[], input?: string) =>
+    spawnSync(process.execPath, [CLI, ...args], { encoding: 'utf8', input });
