diff --git a/packages/core/src/address/english.ts b/packages/core/src/address/english.ts
new file mode 100644
index 0000000..ea1cd6f
--- /dev/null
+++ b/packages/core/src/address/english.ts
@@ -0,0 +1,26 @@
+import { removeDiacritics } from '../shared/diacritics.js';
+import type { Province, Ward } from './data.js';
+
+/** English "street, ward, province" built from bundled `nameEn`; falls back to unaccented `name` with a warning. */
+export function englishAddress(parts: {
+  street?: string;
+  ward?: Ward | string;
+  province: Province | string;
+}): { text: string; warnings: string[] } {
+  const warnings: string[] = [];
+  const unit = (u: Ward | Province | string | undefined): string | undefined => {
+    if (u === undefined) return undefined;
+    if (typeof u === 'string') return removeDiacritics(u);
+    if (u.nameEn) return u.nameEn;
+    warnings.push(`No English name for ${u.fullName}; used the name without diacritics.`);
+    return removeDiacritics(u.name);
+  };
+  const text = [
+    parts.street === undefined ? undefined : removeDiacritics(parts.street),
+    unit(parts.ward),
+    unit(parts.province),
+  ]
+    .filter(Boolean)
+    .join(', ');
+  return { text, warnings };
+}
