+++ b/packages/core/src/address/validate.ts
@@ -0,0 +1,187 @@
+import { fail, type Result } from '../shared/result.js';
+import {
+  LEGACY_PROVINCES,
+  MAPPING,
+  legacyProvinceByCode,
+  wardByCode,
+  type LegacyDistrict,
+  type LegacyProvince,
+  type LegacyWard,
+  type Province,
+  type Ward,
+} from './data.js';
+import { convertAddress } from './convert.js';
+import { matchUnit, tokenize } from './fuzzy.js';
+import { findProvince, searchWards } from './search.js';
+
+export type ValidateReason =
+  'PROVINCE_NOT_FOUND' | 'WARD_NOT_FOUND' | 'WARD_NOT_IN_PROVINCE' | 'LEGACY_WARD';
+
+export interface ValidateSummary {
+  code: string;
+  name: string;
+  fullName: string;
+}
+
+export interface ValidateSuggestion {
+  ward: ValidateSummary;
+  province: ValidateSummary;
+}
+
+export type ValidateAddressOutcome =
+  | { valid: true; province: ValidateSummary; ward: ValidateSummary }
+  | {
+      valid: false;
+      reason: Extract<ValidateReason, 'PROVINCE_NOT_FOUND' | 'WARD_NOT_FOUND'>;
+      message: string;
+    }
+  | {
+      valid: false;
+      reason: Extract<ValidateReason, 'WARD_NOT_IN_PROVINCE'>;
+      message: string;
+      province: ValidateSummary;
+      suggestions: ValidateSuggestion[];
+    }
+  | {
+      valid: false;
+      reason: Extract<ValidateReason, 'LEGACY_WARD'>;
+      message: string;
+      oldWard: ValidateSummary & { district: string; province: string };
+      newWards: Array<ValidateSuggestion & { isDefault: boolean }>;
+      divided: boolean;
+    };
+
+export type ValidateAddressResult = Result<ValidateAddressOutcome>;
+
+const summary = (x: { code: string; name: string; fullName: string }): ValidateSummary => ({
+  code: x.code,
+  name: x.name,
+  fullName: x.fullName,
+});
+
+const isBlank = (v: unknown): boolean => typeof v !== 'string' || v.trim() === '';
+
+function legacyProvincesOf(query: string): LegacyProvince[] {
+  const q = query.trim();
+  if (/^\d{2}$/.test(q)) {
+    const p = legacyProvinceByCode.get(q);
+    return p ? [p] : [];
+  }
+  return matchUnit(tokenize(q), LEGACY_PROVINCES, 0.85)
+    .slice(0, 1)
+    .map((c) => c.item);
+}
+
+function findLegacyWard(
+  provinces: LegacyProvince[],
+  query: string,
+): { ward: LegacyWard; district: LegacyDistrict; province: LegacyProvince } | undefined {
+  const q = query.trim();
+  const t = tokenize(q);
+  for (const province of provinces)
+    for (const district of province.districts) {
+      const ward = /^\d+$/.test(q)
+        ? district.wards.find((w) => w.code === q)
+        : matchUnit(t, district.wards, 0.85)[0]?.item;
+      if (ward) return { ward, district, province };
+    }
+  return undefined;
+}
+
+function exactWardMatches(query: string): Array<{ ward: Ward; province: Province }> {
+  const q = query.trim();
+  if (/^\d+$/.test(q)) {
+    const hit = wardByCode.get(q);
+    return hit ? [hit] : [];
+  }
+  return searchWards(q, undefined, 50).filter((m) => m.score >= 0.98);
+}
+
+/**
+ * Check that a ward belongs to a province (post-01/07/2025 structure). Province and ward accept a code or a name.
+ * Never throws; wards from the pre-2025 structure are reported as LEGACY_WARD with their new ward(s).
+ */
+export function validateAddress(input: unknown): ValidateAddressResult {
+  const o = input !== null && typeof input === 'object' ? (input as Record<string, unknown>) : {};
+  if (isBlank(o.province) || isBlank(o.ward))
+    return fail('EMPTY', 'Both province and ward are required (non-empty strings)');
+  const provinceQ = (o.province as string).trim();
+  const wardQ = (o.ward as string).trim();
+
+  const current = findProvince(provinceQ);
+  const legacy = legacyProvincesOf(provinceQ);
+  if (!current && legacy.length === 0)
+    return {
+      ok: true,
+      valid: false,
+      reason: 'PROVINCE_NOT_FOUND',
+      message: `No province matches "${provinceQ}"`,
+    };
+
+  const exact = exactWardMatches(wardQ);
+  if (current) {
+    const hit = exact.find((m) => m.province.code === current.code);
+    if (hit)
+      return {
+        ok: true,
+        valid: true,
+        province: summary(current),
+        ward: summary(hit.ward),
+      };
+  }
+
+  const oldProvinces = [...legacy];
+  if (current)
+    for (const lp of LEGACY_PROVINCES)
+      if (MAPPING.provinces[lp.key] === current.key && !oldProvinces.includes(lp))
+        oldProvinces.push(lp);
+  const old = findLegacyWard(oldProvinces, wardQ);
+  if (old) {
+    const conv = convertAddress({
+      province: old.province.fullName,
+      district: old.district.fullName,
+      ward: old.ward.fullName,
+    });
+    if (conv.ok && conv.candidates.length > 0) {
+      const divided = conv.candidates.length > 1;
+      return {
+        ok: true,
+        valid: false,
+        reason: 'LEGACY_WARD',
+        message: `${old.ward.fullName} is a pre-2025 ward; it ${divided ? 'was split into' : 'is now'} ${conv.candidates.map((c) => `${c.ward.fullName}, ${c.province.fullName}`).join(' / ')}`,
+        oldWard: {
+          ...summary(old.ward),
+          district: old.district.fullName,
+          province: old.province.fullName,
+        },
+        newWards: conv.candidates.map((c) => ({
+          ward: summary(c.ward),
+          province: summary(c.province),
+          isDefault: c.isDefault,
+        })),
+        divided,
+      };
+    }
+  }
+
+  if (current) {
+    if (exact.length > 0)
+      return {
+        ok: true,
+        valid: false,
+        reason: 'WARD_NOT_IN_PROVINCE',
+        message: `"${wardQ}" is not a ward of ${current.fullName}`,
+        province: summary(current),
+        suggestions: exact.slice(0, 5).map((m) => ({
+          ward: summary(m.ward),
+          province: summary(m.province),
+        })),
+      };
+  }
+  return {
+    ok: true,
+    valid: false,
+    reason: 'WARD_NOT_FOUND',
+    message: `No current or pre-2025 ward matches "${wardQ}" in "${provinceQ}"`,
+  };
+}
