+import * as core from '@vn-skills/core';
+import { loadGolden, title } from './golden.js';
+
+type Validate = (input: unknown) => Record<string, unknown>;
+const validateAddress = (input: unknown) =>
+  (core as unknown as { validateAddress: Validate }).validateAddress(input);
+
+const CLI = resolve(__dirname, '..', 'packages', 'cli', 'dist', 'index.js');
+const SERVER = resolve(__dirname, '..', 'packages', 'mcp', 'dist', 'index.js');
+
+function run(args: string[]) {
+  const r = spawnSync(process.execPath, [CLI, ...args], { encoding: 'utf8' });
+  return {
+    code: r.status,
+    out: r.stdout,
+    json: () => JSON.parse(r.stdout) as Record<string, unknown>,
+  };
+}
+
+interface Case {
+  name?: string;
+  input: unknown;
+  expected: Record<string, unknown>;
+}
+const golden = loadGolden<{ validateAddress: Case[] }>('vn-address');
+
+describe('golden: validateAddress', () => {
+  it.each(golden.validateAddress.map((c) => [title(c), c] as const))('%s', (_, c) =>
+    expect(validateAddress(c.input)).toMatchObject(c.expected),
+  );
+});
+
+describe('validateAddress', () => {
+  it('is exported from core', () =>
+    expect(typeof (core as Record<string, unknown>).validateAddress).toBe('function'));
+
+  it('valid by names with summaries', () => {
