+    };
+    expect(r.reason).toBe('WARD_NOT_IN_PROVINCE');
+    expect(r.suggestions.length).toBeGreaterThan(0);
+    expect(r.suggestions.length).toBeLessThanOrEqual(5);
+    expect(r.suggestions[0]).toMatchObject({ ward: { code: '26740' }, province: { code: '79' } });
+  });
