+    expect(validateAddress(input)).toMatchObject({ ok: false, error: { code: 'EMPTY' } }),
+  );
+});
+
+describe('CLI address validate', () => {
+  it('valid: exit 0 and JSON', () => {
+    const r = run(['--json', 'address', 'validate', '--province', 'HCM', '--ward', 'Sài Gòn']);
+    expect(r.code).toBe(0);
+    expect(r.json()).toMatchObject({ ok: true, valid: true });
+  });
+  it('wrong province: exit 2', () => {
+    const r = run(['--json', 'address', 'validate', '--province', 'Hà Nội', '--ward', 'Sài Gòn']);
+    expect(r.code).toBe(2);
+    expect(r.json()).toMatchObject({ valid: false, reason: 'WARD_NOT_IN_PROVINCE' });
+  });
+  it('old ward of old province: exit 2 LEGACY_WARD', () => {
+    const r = run([
+      '--json',
+      'address',
+      'validate',
+      '--province',
+      'Bình Dương',
+      '--ward',
+      'Phú Lợi',
+    ]);
+    expect(r.code).toBe(2);
+    expect(r.json()).toMatchObject({ reason: 'LEGACY_WARD' });
+  });
+  it('unknown province: exit 2', () => {
+    const r = run(['--json', 'address', 'validate', '--province', 'Atlantis', '--ward', 'x']);
+    expect(r.code).toBe(2);
+    expect(r.json()).toMatchObject({ reason: 'PROVINCE_NOT_FOUND' });
