diff --git a/tests/convert-file-report.test.ts b/tests/convert-file-report.test.ts
new file mode 100644
index 0000000..a1ef472
--- /dev/null
+++ b/tests/convert-file-report.test.ts
@@ -0,0 +1,125 @@
+import { describe, expect, it } from 'vitest';
+import { spawnSync } from 'node:child_process';
+import { existsSync, mkdtempSync, readFileSync, writeFileSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join, resolve } from 'node:path';
+
+const CLI = resolve(__dirname, '..', 'packages', 'cli', 'dist', 'index.js');
+const OLD = 'P. Bến Nghé, Q.1, TP.HCM';
+const BAD = 'asdf qwerty 123';
+
+function run(args: string[]) {
+  const r = spawnSync(process.execPath, [CLI, ...args], { encoding: 'utf8' });
+  return { code: r.status, out: r.stdout, err: r.stderr };
+}
+const dir = () => mkdtempSync(join(tmpdir(), 'vn-skills-'));
+const ndjson = (s: string) =>
+  s
+    .split('\n')
+    .filter((l) => l.trim() !== '')
+    .map((l) => JSON.parse(l) as Record<string, unknown>);
+
+interface Report {
+  total: number;
+  converted: number;
+  failed: number;
+  byMappingType: Record<string, number>;
+  confidence: Record<string, number>;
+  withWarnings: number;
+  review: { row: number; input: string; reason: string }[];
+}
+
+describe('address convert-file --out / --report', () => {
+  it('--out writes NDJSON to the file and nothing to stdout', () => {
+    const d = dir();
+    const input = join(d, 'in.txt');
+    const out = join(d, 'out.ndjson');
+    writeFileSync(input, `${OLD}\n${OLD}\n`);
+    const r = run(['address', 'convert-file', input, '--out', out]);
+    expect(r.code).toBe(0);
+    expect(r.out).toBe('');
+    expect(existsSync(out)).toBe(true);
+    expect(ndjson(readFileSync(out, 'utf8')).map((o) => o.line)).toEqual([1, 2]);
+  });
+
+  it('--report writes totals, buckets and review rows (text mode)', () => {
+    const d = dir();
+    const input = join(d, 'in.txt');
+    const report = join(d, 'report.json');
+    writeFileSync(input, `${OLD}\n\n${BAD}\n`);
+    const r = run(['address', 'convert-file', input, '--report', report]);
+    expect(r.code).toBe(2);
+    expect(r.err).toContain('converted 1, failed 1');
+    expect(ndjson(r.out)).toHaveLength(2);
+    const j = JSON.parse(readFileSync(report, 'utf8')) as Report;
+    expect(j.total).toBe(2);
+    expect(j.converted).toBe(1);
+    expect(j.failed).toBe(1);
+    expect(j.converted + j.failed).toBe(j.total);
+    expect(Object.keys(j.confidence)).toEqual(['<0.5', '0.5–0.7', '0.7–0.9', '≥0.9']);
+    expect(Object.values(j.confidence).reduce((a, b) => a + b, 0)).toBe(j.converted);
+    expect(Object.values(j.byMappingType).reduce((a, b) => a + b, 0)).toBe(j.converted);
+    expect(typeof j.withWarnings).toBe('number');
+    const bad = j.review.find((e) => e.input === BAD);
+    expect(bad).toBeDefined();
+    expect(bad!.row).toBe(3);
+    expect(typeof bad!.reason).toBe('string');
+  });
+
+  it('--report in CSV mode uses 1-based data rows (header excluded)', () => {
+    const d = dir();
+    const input = join(d, 'in.csv');
+    const report = join(d, 'report.json');
+    writeFileSync(input, `id,address\n1,"${OLD}"\n2,"${BAD}"\n`);
+    const r = run(['address', 'convert-file', input, '--csv', '--column', 'address', '--report', report]);
+    expect(r.code).toBe(2);
+    const j = JSON.parse(readFileSync(report, 'utf8')) as Report;
+    expect(j.total).toBe(2);
+    expect(j.review.map((e) => e.row)).toContain(2);
+    expect(j.review.find((e) => e.row === 2)!.input).toBe(BAD);
+  });
+
+  it('--review-below 1 puts every row in review; --only-review emits only those rows', () => {
+    const d = dir();
+    const input = join(d, 'in.txt');
+    const report = join(d, 'report.json');
+    writeFileSync(input, `${OLD}\n${BAD}\n`);
+    const r = run([
+      'address', 'convert-file', input, '--report', report, '--review-below', '1', '--only-review',
+    ]);
+    const j = JSON.parse(readFileSync(report, 'utf8')) as Report;
+    expect(j.review.map((e) => e.row).sort()).toEqual([1, 2]);
+    expect(ndjson(r.out)).toHaveLength(2);
+
+    const r0 = run([
+      'address', 'convert-file', input, '--report', report, '--review-below', '0', '--only-review',
+    ]);
+    const j0 = JSON.parse(readFileSync(report, 'utf8')) as Report;
+    expect(j0.review.map((e) => e.row)).toEqual([2]);
+    expect(ndjson(r0.out).map((o) => o.line)).toEqual([2]);
+  });
+
+  it.each(['1.5', '-0.1', 'abc'])('--review-below %s is INVALID_OPTION in --json mode', (v) => {
+    const d = dir();
+    const input = join(d, 'in.txt');
+    writeFileSync(input, `${OLD}\n`);
+    const r = run(['--json', 'address', 'convert-file', input, '--review-below', v]);
+    expect(r.code).toBe(1);
+    expect(JSON.parse(r.out)).toMatchObject({ ok: false, error: { code: 'INVALID_OPTION' } });
+  });
+
+  it('--json: unwritable --out / --report returns WRITE_ERROR', () => {
+    const d = dir();
+    const input = join(d, 'in.txt');
+    writeFileSync(input, `${OLD}\n`);
+    const missing = join(d, 'no', 'such', 'dir', 'x.json');
+    for (const flag of ['--out', '--report']) {
+      const r = run(['--json', 'address', 'convert-file', input, flag, missing]);
+      expect(r.code).toBe(1);
+      expect(JSON.parse(r.out)).toMatchObject({
+        ok: false,
+        error: { code: 'WRITE_ERROR', message: expect.any(String), hint: expect.any(String) },
+      });
+    }
+  });
+});

