+import { describe, expect, it } from 'vitest';
+import { existsSync, readFileSync } from 'node:fs';
+import { resolve } from 'node:path';
+import {
+  addWorkingDays,
+  buildVietQR,
+  convertAddress,
+  isWorkingDay,
+  moneyToWords,
+  parseCitizenId,
+  parseVietQR,
+  validateTaxId,
+} from '@vn-skills/core';
+import { runOperation } from '../packages/n8n/src/nodes/VnSkills/operations.js';
+import { VnSkills } from '../packages/n8n/src/nodes/VnSkills/VnSkills.node.js';
+
+const PKG_DIR = resolve(__dirname, '..', 'packages', 'n8n');
+const pkg = JSON.parse(readFileSync(resolve(PKG_DIR, 'package.json'), 'utf8')) as {
+  name: string;
+  license: string;
+  keywords: string[];
+  repository: unknown;
+  peerDependencies: Record<string, string>;
+  dependencies?: Record<string, string>;
+  n8n: { n8nNodesApiVersion: number; nodes: string[] };
+};
+
+describe('n8n package metadata', () => {
+  it('follows the n8n community node rules', () => {
+    expect(pkg.name).toBe('@vn-skills/n8n-nodes-vn-skills');
+    expect(pkg.keywords).toContain('n8n-community-node-package');
+    expect(pkg.license).toBe('MIT');
+    expect(pkg.repository).toBeTruthy();
+    expect(pkg.peerDependencies['n8n-workflow']).toBeTruthy();
+    expect(pkg.dependencies?.['n8n-workflow']).toBeUndefined();
+    expect(pkg.n8n.n8nNodesApiVersion).toBeTypeOf('number');
+    expect(pkg.n8n.nodes).toEqual(['dist/nodes/VnSkills/VnSkills.node.js']);
+  });
+
+  it('declared node files exist after build', () => {
+    for (const p of pkg.n8n.nodes) expect(existsSync(resolve(PKG_DIR, p))).toBe(true);
+  });
+});
+
+describe('Vietnam Toolkit node description', () => {
+  const d = new VnSkills().description;
+  const props = d.properties as { name: string; options?: { value: string }[] }[];
+  const ops = props
+    .filter((p) => p.name === 'operation')
+    .flatMap((p) => (p.options ?? []).map((o) => o.value));
+
+  it('has no credentials and a display name', () => {
+    expect(d.displayName).toBe('Vietnam Toolkit');
+    expect(d.credentials ?? []).toEqual([]);
+  });
+
+  it('lists every resource', () => {
+    const resource = props.find((p) => p.name === 'resource');
+    expect(resource?.options?.map((o) => o.value).sort()).toEqual(
+      ['address', 'citizenId', 'holidays', 'money', 'taxId', 'vietqr'].sort(),
+    );
+  });
+
+  it('lists every operation', () => {
+    for (const op of [
+      'build',
+      'parse',
+      'convert',
+      'validate',
+      'toWords',
+      'isWorkingDay',
+      'addWorkingDays',
+    ])
+      expect(ops).toContain(op);
+  });
+});
+
+describe('operations.ts', () => {
+  it('vietqr build', () => {
+    const p = { bank: 'VCB', account: '0123456789', amount: 50000, note: 'test' };
+    const r = runOperation('vietqr', 'build', p);
+    expect(r).toEqual(buildVietQR(p));
+    expect(r.ok && r.payload.startsWith('000201')).toBe(true);
+  });
+
+  it('vietqr parse round-trips a built payload', () => {
+    const b = buildVietQR({ bank: 'VCB', account: '0123456789', amount: 50000 });
+    if (!b.ok) throw new Error('build failed');
+    const r = runOperation('vietqr', 'parse', { payload: b.payload });
+    expect(r).toEqual(parseVietQR(b.payload));
+    expect(r.ok).toBe(true);
+  });
+
+  it('address convert', () => {
+    const text = 'Phường Bến Nghé, Quận 1, Thành phố Hồ Chí Minh';
+    expect(runOperation('address', 'convert', { text })).toEqual(convertAddress(text));
+  });
+
+  it('taxId validate', () => {
+    const r = runOperation('taxId', 'validate', { taxId: '0100233488' });
+    expect(r).toEqual(validateTaxId('0100233488'));
+    expect(r.ok).toBe(true);
+  });
+
+  it('citizenId parse', () => {
+    const id = '001090000001';
+    expect(runOperation('citizenId', 'parse', { id })).toEqual(parseCitizenId(id));
+  });
+
+  it('money toWords', () => {
+    const r = runOperation('money', 'toWords', { amount: 1200000 });
+    expect(r).toEqual(moneyToWords(1200000));
+    expect(r.ok && r.words).toBe('một triệu hai trăm nghìn đồng');
+  });
+
+  it('holidays isWorkingDay', () => {
+    expect(runOperation('holidays', 'isWorkingDay', { date: '2026-03-04' })).toEqual(
+      isWorkingDay(4, 3, 2026),
+    );
+  });
+
+  it('holidays addWorkingDays', () => {
+    expect(runOperation('holidays', 'addWorkingDays', { date: '2026-03-04', n: 3 })).toEqual(
+      addWorkingDays(4, 3, 2026, 3),
+    );
+  });
+});
+
+describe('operations.ts errors return ok:false', () => {
+  const cases: [string, string, Record<string, unknown>][] = [
+    ['vietqr', 'build', { bank: 'NOT-A-BANK', account: '1' }],
+    ['vietqr', 'parse', { payload: 'garbage' }],
+    ['address', 'convert', { text: '' }],
+    ['taxId', 'validate', { taxId: '123' }],
+    ['citizenId', 'parse', { id: '123' }],
+    ['money', 'toWords', { amount: 'abc' }],
+    ['holidays', 'isWorkingDay', { date: '2026-02-30' }],
+    ['holidays', 'addWorkingDays', { date: '2026-03-04', n: 1.5 }],
+  ];
+  for (const [resource, operation, params] of cases) {
+    it(`${resource}.${operation}`, () => {
+      expect(runOperation(resource, operation, params).ok).toBe(false);
+    });
+  }
+});

