+import type { Result } from '@vn-skills/core';
+
+// Core is loaded lazily so the first page load only ships the UI; the bundled data arrives in its own chunk.
+const loadCore = () => import('@vn-skills/core');
+
+const failed = (code: string, message: string): Result<never> =>
+  ({ ok: false, error: { code, message } }) as unknown as Result<never>;
+
+export async function buildVietQRFromForm(f: {
+  bank: string;
+  account: string;
+  amount: string;
+  note: string;
+}) {
+  const core = await loadCore();
+  const amount = f.amount.trim();
+  const note = f.note.trim();
+  return core.buildVietQR({
+    bank: f.bank.trim(),
+    account: f.account.trim(),
+    ...(amount ? { amount: Number(amount) } : {}),
+    ...(note ? { note } : {}),
+  });
+}
+
+export async function parseVietQRFromForm(f: { payload: string }) {
+  return (await loadCore()).parseVietQR(f.payload.trim());
+}
+
+export async function convertAddressFromForm(f: { address: string }) {
+  return (await loadCore()).convertAddress(f.address);
+}
+
+export async function validateTaxIdFromForm(f: { taxId: string }) {
+  return (await loadCore()).validateTaxId(f.taxId.trim());
+}
+
+export async function parseCitizenIdFromForm(f: { id: string }) {
+  return (await loadCore()).parseCitizenId(f.id.trim());
+}
+
+export async function moneyToWordsFromForm(f: { amount: string }) {
+  return (await loadCore()).moneyToWords(f.amount.trim());
+}
+
+export async function lunarFromForm(f: { date: string }) {
+  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(f.date.trim());
+  if (!m) return failed('INVALID_DATE', 'Chọn ngày dương lịch (pick a solar date, YYYY-MM-DD).');
+  return (await loadCore()).lunarInfo(Number(m[3]), Number(m[2]), Number(m[1]));
+}
