+      {
+        title: 'Số tiền (Amount in words)',
+        fields: [{ name: 'amount', label: 'Số tiền VND (Amount)', value: '1500000' }],
+        run: (v) => moneyToWordsFromForm({ amount: v.amount ?? '' }),
+      },
+    ],
+  },
+  {
+    label: 'Âm lịch',
+    forms: [
+      {
+        title: 'Dương lịch → âm lịch (Solar → lunar)',
+        fields: [{ name: 'date', label: 'Ngày dương lịch (Solar date)', type: 'date' }],
+        run: (v) => lunarFromForm({ date: v.date ?? '' }),
+      },
+    ],
+  },
+];
+
+const nav = document.getElementById('tabs')!;
+const app = document.getElementById('app')!;
+
+function el<K extends keyof HTMLElementTagNameMap>(tag: K, text?: string) {
+  const e = document.createElement(tag);
+  if (text) e.textContent = text;
+  return e;
+}
+
+function renderForm(form: Form): HTMLElement {
+  const box = el('section');
+  box.append(el('h3', form.title));
+  const f = el('form');
+  const inputs: Record<string, HTMLInputElement | HTMLTextAreaElement> = {};
+  for (const fld of form.fields) {
+    const label = el('label', fld.label + ' ');
+    const input = fld.area ? el('textarea') : el('input');
+    if (input instanceof HTMLInputElement && fld.type) input.type = fld.type;
+    input.value = fld.value ?? '';
+    inputs[fld.name] = input;
+    label.append(input);
+    f.append(label, el('br'));
+  }
+  f.append(el('button', 'Chạy (Run)'));
+  const out = el('pre');
+  f.addEventListener('submit', (ev) => {
+    ev.preventDefault();
+    const values = Object.fromEntries(Object.entries(inputs).map(([k, i]) => [k, i.value]));
+    form
+      .run(values)
+      .then((r) => {
+        out.textContent = JSON.stringify(r, null, 2);
+      })
+      .catch((e: unknown) => {
+        out.textContent = String(e);
+      });
+  });
+  box.append(f, out);
+  return box;
+}
+
+function show(tab: Tab) {
+  app.replaceChildren();
+  if (tab.note) app.append(el('p', tab.note));
+  for (const form of tab.forms) app.append(renderForm(form));
+}
+
+for (const tab of tabs) {
+  const b = el('button', tab.label);
+  b.type = 'button';
+  b.addEventListener('click', () => show(tab));
+  nav.append(b);
+}
+show(tabs[0]!);
