+import { describe, expect, it } from 'vitest';
+import { execSync } from 'node:child_process';
+import { existsSync, readdirSync, readFileSync } from 'node:fs';
+import { join, resolve } from 'node:path';
+import {
+  buildVietQR,
+  convertAddress,
+  lunarInfo,
+  moneyToWords,
+  parseCitizenId,
+  parseVietQR,
+  validateTaxId,
+} from '@vn-skills/core';
+import {
+  buildVietQRFromForm,
+  convertAddressFromForm,
+  lunarFromForm,
+  moneyToWordsFromForm,
+  parseCitizenIdFromForm,
+  parseVietQRFromForm,
+  validateTaxIdFromForm,
+} from '../packages/playground/src/handlers.js';
+
+const PKG = resolve(__dirname, '..', 'packages', 'playground');
+
+describe('playground handlers (form input -> core call -> Result)', () => {
+  it('VietQR build: matches core buildVietQR', async () => {
+    const r = await buildVietQRFromForm({
+      bank: 'VCB',
+      account: '0011001234567',
+      amount: '',
+      note: '',
+    });
+    expect(r).toEqual(buildVietQR({ bank: 'VCB', account: '0011001234567' }));
+    expect(r.ok && r.payload.startsWith('000201010211')).toBe(true);
+  });
+  it('VietQR build: converts the amount string to a number', async () => {
+    const r = await buildVietQRFromForm({
+      bank: 'VCB',
+      account: '123',
+      amount: '50000',
+      note: 'abc',
+    });
+    expect(r).toEqual(buildVietQR({ bank: 'VCB', account: '123', amount: 50000, note: 'abc' }));
+  });
+  it('VietQR build: unknown bank is a failed Result, not a throw', async () => {
+    const r = await buildVietQRFromForm({
+      bank: 'NOPE-BANK',
+      account: '123',
+      amount: '',
+      note: '',
+    });
+    expect(r).toMatchObject({ ok: false, error: { code: 'BANK_NOT_FOUND' } });
+  });
+  it('VietQR parse: round-trips a built payload', async () => {
+    const built = buildVietQR({ bank: 'VCB', account: '0011001234567' });
+    if (!built.ok) throw new Error('build failed');
+    const r = await parseVietQRFromForm({ payload: built.payload });
+    expect(r).toEqual(parseVietQR(built.payload));
+    expect(r.ok).toBe(true);
+  });
+  it('VietQR parse: garbage payload fails', async () => {
+    expect(await parseVietQRFromForm({ payload: 'xyz' })).toMatchObject({ ok: false });
+  });
+  it('address: converts old -> new like core', async () => {
+    const text = 'Xã Tân Thạnh, Huyện Thới Lai, Cần Thơ';
+    const r = await convertAddressFromForm({ address: text });
+    expect(r).toEqual(convertAddress(text));
+  });
+  it('address: empty input fails', async () => {
+    const r = await convertAddressFromForm({ address: '' });
+    expect(r.ok).toBe(false);
+  });
+  it('tax ID: valid and invalid inputs', async () => {
+    expect(await validateTaxIdFromForm({ taxId: '0100233488-001' })).toEqual(
+      validateTaxId('0100233488-001'),
+    );
+    expect(await validateTaxIdFromForm({ taxId: 'abc' })).toMatchObject({
+      ok: false,
+      error: { code: 'INVALID_FORMAT' },
+    });
+  });
+  it('CCCD: parses like core and rejects non-digits', async () => {
+    expect(await parseCitizenIdFromForm({ id: '123456789' })).toMatchObject({
+      ok: true,
+      kind: 'cmnd',
+    });
+    expect(await parseCitizenIdFromForm({ id: '001900123456' })).toEqual(
+      parseCitizenId('001900123456'),
+    );
+    expect(await parseCitizenIdFromForm({ id: '04809012345a' })).toMatchObject({ ok: false });
+  });
+  it('money in words: string amount and NaN', async () => {
+    expect(await moneyToWordsFromForm({ amount: '1500000' })).toEqual(moneyToWords('1500000'));
+    expect(await moneyToWordsFromForm({ amount: 'abc' })).toMatchObject({ ok: false });
+  });
+  it('lunar: picked solar date (YYYY-MM-DD) maps to lunarInfo', async () => {
+    const r = await lunarFromForm({ date: '2025-01-29' });
+    expect(r).toEqual(lunarInfo(29, 1, 2025));
+  });
+  it('lunar: empty date fails', async () => {
+    expect(await lunarFromForm({ date: '' })).toMatchObject({ ok: false });
+  });
+});
+
+describe('playground build', () => {
+  it('is a private workspace package', () => {
+    const pkg = JSON.parse(readFileSync(join(PKG, 'package.json'), 'utf8')) as {
+      private?: boolean;
+    };
+    expect(pkg.private).toBe(true);
+  });
+
+  it('builds a static site with no remote URLs and a lazy address chunk', () => {
+    execSync('pnpm --filter ./packages/playground build', {
+      cwd: resolve(PKG, '..', '..'),
+      stdio: 'pipe',
+    });
+    const dist = join(PKG, 'dist');
+    expect(existsSync(join(dist, 'index.html'))).toBe(true);
+    const html = readFileSync(join(dist, 'index.html'), 'utf8');
+    expect(html).not.toMatch(/(src|href)=["']https?:\/\//);
+    const assets = join(dist, 'assets');
+    const js = readdirSync(assets).filter((f) => f.endsWith('.js'));
+    expect(js.length).toBeGreaterThan(1);
+    for (const f of js) {
+      const code = readFileSync(join(assets, f), 'utf8');
+      expect(code).not.toMatch(/(?:src|href|url|fetch|import)\s*[=(]\s*["'`]https?:\/\//);
+    }
+  });
+});

