+      'SO_THANH_CHU',
+      'MST',
+      'AM_LICH',
+      'NGAY_LAM_VIEC',
+      'CONG_NGAY_LAM_VIEC',
+    ]) {
+      expect(ids).toContain(required);
+    }
+    for (const f of meta.functions) {
+      expect(f.description?.length).toBeGreaterThan(0);
+      expect(f.parameters.length).toBeGreaterThan(0);
