+      .map((f) => readFileSync(resolve(src, f), 'utf8'))
+      .join('\n');
+    expect(text).toMatch(/from ['"][^'"]*sheets[^'"]*['"]/);
+    expect(text).not.toMatch(/moneyToWords\(|validateTaxId\(|lunarInfo\(/);
