+    expect(fns.TIEN_CHU!(1500000, [['ngàn']])).toBe(k.ok && k.words);
+    expect(fns.TIEN_CHU!([[1500000], [1500000]], [['ngàn']])).toEqual([
+      [k.ok && k.words],
+      [k.ok && k.words],
+    ]);
+  });
