+describe('lunarMonthCalendar', () => {
+  const cal = (m: number, y: number) => {
+    const r = lunarMonthCalendar(m, y);
+    if (!r.ok) throw new Error(r.error.message);
+    return r.days;
+  };
+  it.each([
